(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.015+t*0.3)*20 + Math.cos(y*0.012-t*0.2)*15;
  const w1y = Math.cos(y*0.015-t*0.25)*20 + Math.sin(x*0.013+t*0.35)*15;
  const w2x = Math.sin(x*0.04+t*0.7)*5 + Math.cos(y*0.035-t*0.5)*4;
  const w2y = Math.cos(y*0.04-t*0.6)*5 + Math.sin(x*0.038+t*0.8)*4;
  const sx = x + w1x + w2x, sy = y + w1y + w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 1.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.9],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 1.1],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0.8],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 1.2],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 0.85],
    [80+Math.sin(t*0.45+3)*60, 40+Math.cos(t*0.65+2)*40, 0.14, 1.3, 0.7],
    [400+Math.cos(t*0.55+1)*70, 200+Math.sin(t*0.75+4)*50, 0.11, 2.1, 1.05]
  ];
  let act = 0, inh = 0, tw = 0;
  for (const [sX, sY, f, sp, w] of src) {
    const d = Math.sqrt((sx-sX)**2 + (sy-sY)**2);
    const fo = 1.0/(1.0+d*0.003);
    act += Math.sin(d*f - t*sp)*w*fo;
    inh += Math.sin(d*f*0.65 + t*sp*0.55 + 1.5)*w*fo;
    tw += w*fo;
  }
  act /= tw; inh /= tw;
  const fine = [[200+Math.sin(t*1.2)*60, 100+Math.cos(t*0.9)*40, 0.25, 3.0], [280+Math.cos(t)*50, 140+Math.sin(t*1.1)*30, 0.3, 2.5]];
  let fi = 0;
  for (const [fX, fY, f, sp] of fine) { const d = Math.sqrt((sx-fX)**2+(sy-fY)**2); fi += Math.sin(d*f-t*sp)*0.5; }
  const bg = (Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1)+Math.sin(sx*0.05+sy*0.05-t*0.6))/3;
  const micro = Math.sin(sx*0.12+sy*0.08+t*2.5)*0.15+Math.sin((sx-sy)*0.15-t*3)*0.1;
  const dist = Math.sqrt((sx-cx)**2+(sy-cy)**2), ang = Math.atan2(sy-cy, sx-cx);
  const spiral = (Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2)+Math.sin(dist*0.07-ang*2-t*0.8))*0.3;
  const pulse = Math.sin(dist*0.08-t*2.0)*Math.exp(-dist*0.005)*0.3;
  const reaction = Math.tanh((act-inh*0.65+bg*0.25+spiral*0.4+pulse+micro+fi*0.3)*2.0);
  const cell = Math.tanh((Math.sin(sx*0.18)*Math.sin(sy*0.18)+Math.sin((sx+sy)*0.12+t)*0.4+Math.sin(sx*0.09-t*0.5)*Math.cos(sy*0.11+t*0.7)*0.3)*1.8)*0.25;
  const edge = Math.abs(reaction)>0.6?Math.pow(Math.abs(reaction),0.5):0;
  const blend = reaction*0.7+cell*0.2+edge*0.1, v = blend*0.5+0.5;
  const pal = [[5,12,52],[12,45,85],[18,95,120],[25,155,140],[120,190,130],[210,195,70],[220,145,60],[195,80,55],[150,40,55],[85,18,55],[30,10,45],[5,12,52]];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const lum = 0.75+Math.sin(reaction*Math.PI)*0.2+edge*0.15, bloom = edge>0?edge*0.3:0;
  return [
    Math.min(255, (pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum+bloom*40)|0,
    Math.min(255, (pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum+bloom*25)|0,
    Math.min(255, (pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum+bloom*15)|0
  ];
}
